package com.smartlibrary.algorithms.flow;import java.util.*;
public final class EdmondsKarp {private EdmondsKarp(){}public static int maxFlow(int[][] capacity,int source,int sink){int n=capacity.length;if(source<0||sink<0||source>=n||sink>=n||source==sink)throw new IllegalArgumentException("Invalid source/sink");int[][] r=new int[n][n];for(int i=0;i<n;i++){if(capacity[i].length!=n)throw new IllegalArgumentException("Capacity matrix must be square");for(int j=0;j<n;j++){if(capacity[i][j]<0)throw new IllegalArgumentException("Negative capacity");r[i][j]=capacity[i][j];}}int flow=0;while(true){int[] parent=new int[n];Arrays.fill(parent,-1);parent[source]=source;Queue<Integer> q=new ArrayDeque<>();q.add(source);while(!q.isEmpty()&&parent[sink]==-1){int u=q.remove();for(int v=0;v<n;v++)if(parent[v]==-1&&r[u][v]>0){parent[v]=u;q.add(v);}}if(parent[sink]==-1)break;int aug=Integer.MAX_VALUE;for(int v=sink;v!=source;v=parent[v])aug=Math.min(aug,r[parent[v]][v]);for(int v=sink;v!=source;v=parent[v]){int u=parent[v];r[u][v]-=aug;r[v][u]+=aug;}flow+=aug;}return flow;}}
